Given an array of integers, the task is to find the maximum absolute difference between the nearest left and the right smaller element of every element in the array. Note: If there is no smaller element on right side or left side of any element then we take zero as the smaller element. For example for the leftmost element, the nearest smaller element on the left side is considered as 0. Similarly, for rightmost elements, the smaller element on the right side is considered as 0.Examples: Input: arr[] = [2, 1, 8]Output: 1Explanation: Left smaller  ls[] = [0, 0, 1], Right smaller rs[] = [1, 0, 0]Maximum Diff of abs(ls[i] - rs[i]) = 1 Input: arr[] = [2, 4, 8, 7, 7, 9, 3]Output: 4Explanation: Left smaller  ls[] = [0, 2, 4, 4, 4, 7, 2], Right smaller  rs[] = [0, 3, 7, 3, 3, 3, 0]Maximum Diff of abs(ls[i] - rs[i]) = 7 - 3 = 4 Table of Content[Naive Approach] Using Nested Loop – O(n2) Time and O(1) Space[Expected Approach] Using Single Stack – O(n) Time and O(n) Space[Naive Approach] Using Nested Loop – O(n^2) Time and O(1) SpaceFor each element in the array: Iterate to the left and find the nearest smaller element to the left similarly iterate to the right and find the nearest smaller element to the right.Calculate the absolute difference between the two smallest values (left smaller and right smaller).Track the maximum absolute difference across all elements.
            C++

    // C++ code to find maximum absolute difference between nearest left and right smaller elements

#include <cmath>
#include <iostream>
#include <vector>
using namespace std;

int findMaxDiff(vector<int> &arr)
{
    int n = arr.size();
    int res = 0;

    // Iterate over each element
    for (int i = 0; i < n; ++i)
    {
        int leftSmaller = 0, rightSmaller = 0;

        // Find nearest smaller element on the left
        for (int j = i - 1; j >= 0; --j)
        {
            if (arr[j] < arr[i])
            {
                leftSmaller = arr[j];
                break;
            }
        }

        // Find nearest smaller element on the right
        for (int j = i + 1; j < n; ++j)
        {
            if (arr[j] < arr[i])
            {
                rightSmaller = arr[j];
                break;
            }
        }

        // Calculate the absolute difference between
        // left and right smaller elements
        int diff = abs(leftSmaller - rightSmaller);

        // Track the maximum difference
        res = max(res, diff);
    }

    return res;
}

int main()
{
    vector<int> arr = {2, 1, 8};
    cout << findMaxDiff(arr) << endl;
    return 0;
}


